// categories list removed (was unused) — category options are rendered inline in the JSX

export default function App() {
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [selectedPrice, setSelectedPrice] = useState("All");

  const filteredProducts = products.filter((product) => {
  // Category Filter
  const categoryMatch =
    selectedCategory === "All" ||
    product.category === selectedCategory;

  // Price Filter
  let priceMatch = true;

  if (selectedPrice === "Under1000") {
    priceMatch = product.price < 1000;
  } else if (selectedPrice === "1000to1500") {
    priceMatch =
      product.price >= 1000 &&
      product.price <= 1500;
  } else if (selectedPrice === "Above1500") {
    priceMatch = product.price > 1500;
  }

  return categoryMatch && priceMatch;
});
  return (
    <>
    <Topnav/>
    <div className="app-container1">
      <h1>Products List</h1>

<div className="filters">
  {/* Category Filter */}
  <select 
    value={selectedCategory}
    onChange={(e) => setSelectedCategory(e.target.value)}
  >
    <option value="All">All Categories</option>
    <option value="Yarn">Yarn</option>
    <option value="Beads">Beads</option>
    <option value="Paints">Paints</option>
    <option value="Paper Craft">Paper Craft</option>
    <option value="Tools">Tools</option>
    <option value="Accessories">Accessories</option>
    <option value="Canvas">Canvas</option>
    <option value="Embroidery">Embroidery</option>
  </select>

  {/* Price Filter */}
  <select
    value={selectedPrice}
    onChange={(e) => setSelectedPrice(e.target.value)}
  >
    <option value="All">All Prices</option>
    <option value="Under1000">Under Rs.1000</option>
    <option value="1000to1500">Rs.1000 - Rs.1500</option>
    <option value="Above1500">Above Rs.1500</option>
  </select>
</div>

<div className="app-container2">
  {filteredProducts.map((product) => (
    <CardComponent
      key={product.id}
      product={product}
    />
  ))}
</div>
    </div>
    </>
  )
}
